const LocaleContext = createContext(null);

const normaliseLocale = (value) => value === 'sw' ? 'sw' : 'en';

const readStoredLocale = (fallback) => {
    if (typeof window === 'undefined') return normaliseLocale(fallback);
    try {
        const stored = window.localStorage.getItem('takeer_locale');
        if (stored) return normaliseLocale(stored);
    } catch (_) {
        // Storage can be unavailable in private browsing; use the server value.
    }
    const browserLocale = (window.navigator.language || '').toLowerCase().startsWith('sw') ? 'sw' : 'en';
    return normaliseLocale(fallback || browserLocale);
};

const resolveTranslation = (locale, key) => key.split('.').reduce((value, part) => value?.[part], translations[locale]);

const interpolate = (value, variables = {}) => String(value).replace(/\{(\w+)\}/g, (_, key) => (
    variables[key] === undefined || variables[key] === null ? `{${key}}` : variables[key]
));

export function LocaleProvider({ children, initialLocale = 'en' }) {
    const [locale, setLocaleState] = useState(() => readStoredLocale(initialLocale));

    useEffect(() => {
        document.documentElement.lang = LOCALES[locale].htmlLang;
        try {
            window.localStorage.setItem('takeer_locale', locale);
        } catch (_) {
            // Ignore unavailable storage; the active page still changes language.
        }
    }, [locale]);

    const setLocale = useCallback(async (nextLocale) => {
        const next = normaliseLocale(nextLocale);
        setLocaleState(next);
        try {
            await axios.post('/locale', { locale: next });
        } catch (_) {
            // The browser preference remains authoritative if the session request fails.
        }
    }, []);

    const t = useCallback((key, variables = {}, fallback = null) => {
        const value = resolveTranslation(locale, key) ?? resolveTranslation('en', key) ?? fallback ?? key;
        return typeof value === 'string' ? interpolate(value, variables) : value;
    }, [locale]);

    const copy = useCallback((english, swahili) => locale === 'sw' ? swahili : english, [locale]);

    const value = useMemo(() => ({
        locale,
        locales: LOCALES,
        isSwahili: locale === 'sw',
        setLocale,
        t,
        copy,
    }), [locale, setLocale, t, copy]);

    return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLocale() {
    const context = useContext(LocaleContext);
    if (!context) throw new Error('useLocale must be used inside LocaleProvider');
    return context;
}
